import React from 'react';
import './App.css';
import './themes.css';
import './styles/design-system.css';
import { Card } from './components/Card';
import { Metronome } from './components/Metronome';
import { Timer } from './components/Timer';
import { NoteSelector } from './components/NoteSelector';
import { GuitarNeck } from './components/GuitarNeck';
import { ChordProgression } from './components/ChordProgression';
import { CircleOfFifths } from './components/CircleOfFifths';
import { NoteTrainer } from './components/NoteTrainer';
import { HarmonyMaker } from './components/HarmonyMaker';
import { JamCard } from './components/JamCard';
import { DesignSystemPreview } from './ui/DesignSystemPreview';
import { Select, Button, ToggleButtonGroup } from './ui';
import { useStore, configurationPresets } from './store/useStore';
import { themes, injectThemeStyles } from './utils/themeGenerator';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core';
import {
  SortableContext,
  sortableKeyboardCoordinates,
  horizontalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

// The guitarNeck card shows either the Fretboard or Piano view — the card
// title reflects whichever is active. Other cards keep the title from the store.
const displayTitle = (card: { id: string; title: string }, viewMode: string): string => {
  if (card.id === 'guitarNeck') {
    return viewMode === 'piano' ? 'Piano' : 'Fretboard';
  }
  return card.title;
};

const DraggableToggle: React.FC<{ card: any }> = ({ card }) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: card.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.7 : 1,
  };

  const { toggleCard, viewMode } = useStore();

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`card-toggle ${card.id} ${card.isActive ? 'active' : ''} ${isDragging ? 'dragging' : ''}`}
      {...attributes}
      {...listeners}
    >
      <div className="toggle-content">
        <input
          type="checkbox"
          checked={card.isActive}
          onChange={() => toggleCard(card.id)}
          onClick={(e) => e.stopPropagation()}
        />
        <span onClick={() => toggleCard(card.id)}>{displayTitle(card, viewMode)}</span>
      </div>
      <div className="drag-icon">
        <div className="drag-dots">
          <div className="dot"></div>
          <div className="dot"></div>
          <div className="dot"></div>
          <div className="dot"></div>
          <div className="dot"></div>
          <div className="dot"></div>
        </div>
      </div>
    </div>
  );
};

function App() {
  const {
    cards, reorderCards, theme, setTheme, applyConfiguration, currentConfiguration,
    viewMode, setViewMode,
  } = useStore();

  // Hash-gated design-system preview. Navigate to `…/#design` to view every
  // primitive in one place; return to the app by clearing the hash. Updates
  // live as the user changes the hash so we don't force a reload.
  const [hash, setHash] = React.useState<string>(() => window.location.hash);
  React.useEffect(() => {
    const onHash = () => setHash(window.location.hash);
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, []);

  // Inject dynamic theme styles on mount
  React.useEffect(() => {
    injectThemeStyles();
  }, []);

  // Apply theme class to document body
  React.useEffect(() => {
    document.body.className = `theme-${theme}`;
  }, [theme]);

  // All hooks must be declared before any early return — React's rules of
  // hooks require consistent call order across renders.
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 5,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Short-circuit: the preview page doesn't need the cards or theme chrome.
  // Everything below is skipped when the hash is set.
  if (hash === '#design') {
    return <DesignSystemPreview />;
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = cards.findIndex(card => card.id === active.id);
      const newIndex = cards.findIndex(card => card.id === over.id);
      
      if (oldIndex !== -1 && newIndex !== -1) {
        reorderCards(oldIndex, newIndex);
      }
    }
  };
  
  const renderCardContent = (card: any) => {
    switch (card.id) {
      case 'metronome':
        return <Metronome />;
      case 'timer':
        return <Timer />;
      case 'noteSelector':
        return <NoteSelector />;
      case 'guitarNeck':
        return <GuitarNeck />;
      case 'chordProgression':
        return <ChordProgression />;
      case 'circleOfFifths':
        return <CircleOfFifths />;
      case 'noteTrainer':
        return <NoteTrainer />;
      case 'harmonyMaker':
        return <HarmonyMaker />;
      case 'jam':
        return <JamCard />;
      default:
        return null;
    }
  };
  
  // Process cards in exact toggle order
  const processCardsInOrder = () => {
    const orderedElements: any[] = [];
    let pendingHorizontalCards: any[] = [];
    
    cards.forEach((card, index) => {
      if (!card.isActive) return;
      
      if (card.layout === 'vertical') {
        // If we have pending horizontal cards, render them first
        if (pendingHorizontalCards.length > 0) {
          orderedElements.push({
            type: 'horizontal-group',
            cards: [...pendingHorizontalCards],
            key: `horizontal-${orderedElements.length}`
          });
          pendingHorizontalCards = [];
        }
        
        // Add the vertical card
        orderedElements.push({
          type: 'vertical',
          card: card,
          key: card.id
        });
      } else {
        // Collect horizontal cards
        pendingHorizontalCards.push(card);
      }
    });
    
    // Add any remaining horizontal cards
    if (pendingHorizontalCards.length > 0) {
      orderedElements.push({
        type: 'horizontal-group',
        cards: pendingHorizontalCards,
        key: `horizontal-${orderedElements.length}`
      });
    }
    
    return orderedElements;
  };
  
  const orderedElements = processCardsInOrder();

  return (
    <div className={`app theme-${theme}`}>
      <header className="app-header">
        <h1>Guitar Practice</h1>
        <p className="contact-info">Questions, bug reports, or feature requests? Contact me at <a href="mailto:canderson1192@gmail.com">canderson1192@gmail.com</a></p>
        <div className="header-controls">
          <div className="header-selector">
            <label>Configuration:</label>
            <Select
              size="sm"
              value={currentConfiguration}
              onChange={(e) => applyConfiguration(e.target.value)}
              options={configurationPresets.map(p => ({ value: p.id, label: p.name }))}
            />
          </div>
          <div className="header-selector">
            <label>Theme:</label>
            <Select
              size="sm"
              value={theme}
              onChange={(e) => setTheme(e.target.value as any)}
              options={Object.entries(themes).map(([id, data]) => ({ value: id, label: data.name }))}
            />
          </div>
          <div className="header-selector">
            <label>View:</label>
            <ToggleButtonGroup label="View mode" layout="segmented">
              <Button
                variant="ghost"
                size="sm"
                active={viewMode === 'fretboard'}
                onClick={() => setViewMode('fretboard')}
              >
                Fretboard
              </Button>
              <Button
                variant="ghost"
                size="sm"
                active={viewMode === 'piano'}
                onClick={() => setViewMode('piano')}
              >
                Piano
              </Button>
            </ToggleButtonGroup>
          </div>
        </div>
      </header>
      
      <main className="app-main">

        {/* Draggable Card Controls */}
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <SortableContext
            items={cards.map(card => card.id)}
            strategy={horizontalListSortingStrategy}
          >
            <div className="card-controls">
              {cards.map(card => (
                <DraggableToggle key={card.id} card={card} />
              ))}
            </div>
          </SortableContext>
        </DndContext>

        {/* Cards Display - Exact Toggle Order */}
        <div className="cards-container">
          {orderedElements.map(element => {
            if (element.type === 'vertical') {
              return (
                <div key={element.key} className="card-container vertical-card" data-layout={element.card.layout}>
                  <Card 
                    title={displayTitle(element.card, viewMode)}
                    isActive={element.card.isActive}
                  >
                    {renderCardContent(element.card)}
                  </Card>
                </div>
              );
            } else if (element.type === 'horizontal-group') {
              // Smart distribution: balance cards between columns while preserving order
              const distributeCards = (cards: any[]) => {
                const leftCards: any[] = [];
                const rightCards: any[] = [];
                
                // Define card weights based on typical content size
                const cardWeights: { [key: string]: number } = {
                  'metronome': 2,          // Medium height
                  'timer': 2,              // Medium height
                  'noteSelector': 3,       // Tall (scale selector + notes)
                  'noteTrainer': 3,        // Tall (auto-advance controls + large note display)
                  'chordProgression': 2,   // Medium height (chord list)
                  'circleOfFifths': 4,     // Very tall (large circle diagram)
                  'harmonyMaker': 4,       // Wide (dual fretboards)
                  'jam': 3,               // Medium-tall (controls + chord display)
                  'guitarNeck': 5          // Tallest (but vertical, won't be here)
                };
                
                let leftWeight = 0;
                let rightWeight = 0;
                
                // Distribute cards in original order, choosing column based on current weight
                cards.forEach(card => {
                  const cardWeight = cardWeights[card.id] || 2;
                  
                  if (leftWeight <= rightWeight) {
                    leftCards.push(card);
                    leftWeight += cardWeight;
                  } else {
                    rightCards.push(card);
                    rightWeight += cardWeight;
                  }
                });
                
                return { leftCards, rightCards };
              };
              
              const { leftCards, rightCards } = distributeCards(element.cards);
              
              return (
                <div key={element.key} className="horizontal-section">
                  <div className="column">
                    {leftCards.map((card: any) => (
                      <div key={card.id} className="card-container" data-layout={card.layout}>
                        <Card 
                          title={displayTitle(card, viewMode)}
                          isActive={card.isActive}
                        >
                          {renderCardContent(card)}
                        </Card>
                      </div>
                    ))}
                  </div>
                  <div className="column">
                    {rightCards.map((card: any) => (
                      <div key={card.id} className="card-container" data-layout={card.layout}>
                        <Card 
                          title={displayTitle(card, viewMode)}
                          isActive={card.isActive}
                        >
                          {renderCardContent(card)}
                        </Card>
                      </div>
                    ))}
                  </div>
                </div>
              );
            }
            
            return null;
          })}
        </div>
      </main>
    </div>
  );
}

export default App;